export const clamp=(n,min,max)=>Math.max(min,Math.min(max,n));
export function fitRect(width,height,box={x:40,y:40,width:920,height:850}){const ratio=Math.min(box.width/width,box.height/height);return {x:box.x+(box.width-width*ratio)/2,y:box.y+(box.height-height*ratio)/2,width:width*ratio,height:height*ratio};}
export function logoDimensions(state,aspect){const angle=state.angle*Math.PI/180,w=state.size*10,h=w/aspect,rotatedW=Math.abs(Math.cos(angle))*w+Math.abs(Math.sin(angle))*h,rotatedH=Math.abs(Math.sin(angle))*w+Math.abs(Math.cos(angle))*h,scale=Math.min(1,920/rotatedW,850/rotatedH);return {width:w*scale,height:h*scale};}
export function constrainLogo(state,aspect){const {width,height}=logoDimensions(state,aspect),angle=state.angle*Math.PI/180;const halfX=(Math.abs(Math.cos(angle))*width+Math.abs(Math.sin(angle))*height)/2,halfY=(Math.abs(Math.sin(angle))*width+Math.abs(Math.cos(angle))*height)/2;return {...state,x:clamp(state.x,halfX,1000-halfX),y:clamp(state.y,halfY,930-halfY)};}
export function hitLogo(point,state,aspect){const a=-state.angle*Math.PI/180,dx=point.x-state.x,dy=point.y-state.y,x=dx*Math.cos(a)-dy*Math.sin(a),y=dx*Math.sin(a)+dy*Math.cos(a),{width,height}=logoDimensions(state,aspect);return Math.abs(x)<=width/2+12&&Math.abs(y)<=height/2+12;}
